451	     * at least {@code 1}.
452	     */
453	    public Integer getMembershipPoints() {
454	        int points = 0;
455	        boolean hasEmail = this.email != null && !this.email.isBlank();
456	        if (hasEmail) {
457	            points += 2;
458	        }
459	        if (this.namesakeCount != null && this.namesakeCount == 0) {
460	            points += 1;
461	        }
462	        if (this.householdSize != null && this.householdSize >= 3) {
463	            points += 2;
464	        }
465	        Integer registrationFiscalYear = fiscalYearOf(this.registrationDate);
466	        if (registrationFiscalYear != null) {
467	            int elapsedFiscalYears = fiscalYearOf(LocalDate.now()) - registrationFiscalYear;
468	            if (elapsedFiscalYears >= 1) {
469	                points += 3;
470	            }
471	        }
472	        return points;
473	    }
474	
475	    /**
476	     * Return the owner's membership level, a number from {@code 1} to {@code 4},
477	     * derived from {@link #getMembershipPoints()}: {@code 1} for {@code 0-1}
478	     * points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
479	     * {@code 4} for {@code 6} or more.
480	     */
481	    public Integer getMembershipLevel() {
482	        int points = getMembershipPoints();
483	        if (points >= 6) {
484	            return 4;
485	        }
486	        if (points >= 4) {
487	            return 3;
488	        }
489	        if (points >= 2) {
490	            return 2;
491	        }
492	        return 1;
493	    }
494	
495	    public void setNamesakeCount(Integer namesakeCount) {
496	        this.namesakeCount = namesakeCount;
497	    }
498	
499	    public Integer getHouseholdSize() {
500	        return this.householdSize;
501	    }
502	
503	    public void setHouseholdSize(Integer householdSize) {
504	        this.householdSize = householdSize;
505	    }
506	
507	    /**
508	     * Whether this owner, when created, softly matched an existing owner by
509	     * sharing the same last name and postcode but with a different telephone.
510	     * Such an owner is still created; the flag surfaces the likely duplication.
511	     */
512	    public Boolean getPossibleDuplicate() {
513	        return this.possibleDuplicate;
514	    }
515	
516	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
517	        this.possibleDuplicate = possibleDuplicate;
518	    }
519	
520	    /**
521	     * The id of the existing owner this owner softly matched on last name and
522	     * postcode (with a different telephone), or {@code null} when there is no
523	     * such match.
524	     */
525	    public Integer getPossibleDuplicateOf() {
526	        return this.possibleDuplicateOf;
527	    }
528	
529	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
530	        this.possibleDuplicateOf = possibleDuplicateOf;
531	    }
532	
533	    /**
534	     * Whether this owner has been soft-deleted. A newly created owner is not
535	     * deleted; {@code DELETE /api/owners/{id}} sets this flag rather than removing
536	     * the row, and a flagged owner is ignored by the create endpoint's duplicate
537	     * and identity checks.
538	     */
539	    public boolean isDeleted() {
540	        return this.deleted;
541	    }
542	
543	    public void setDeleted(boolean deleted) {
544	        this.deleted = deleted;
545	    }
546	
547	    /**
548	     * Whether more than 80 owners had already been registered on this owner's
549	     * registration day at the time it was created, flagging a bulk-signup surge.
550	     */
551	    public Boolean getBulkSignupWarning() {
552	        return this.bulkSignupWarning;
553	    }
554	
555	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
556	        this.bulkSignupWarning = bulkSignupWarning;
557	    }
558	
559	    /**
560	     * Return the owner's locality (region), preferring the postcode: when the
561	     * postcode is present and falls within a known region's inclusive range
562	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), that
563	     * region is returned. Otherwise the value falls back to the fixed
564	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
565	     * {@code Brisbane -> QLD}), or {@code 'UNKNOWN'} when the city is not in the
566	     * table. This yields the same region for known cities but disambiguates
567	     * cities that share a name.
568	     */
569	    public String getLocality() {
570	        String regionFromPostcode = regionForPostcode();
571	        if (regionFromPostcode != null) {
572	            return regionFromPostcode;
573	        }
574	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
575	    }
576	
577	    /**
578	     * Return the owner's IANA timezone, derived from the locality/region via the
579	     * fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
580	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or
581	     * {@code null} when the region is not in the table.
582	     */
583	    public String getTimezone() {
584	        return REGION_TIMEZONE.get(getLocality());
585	    }
586	
587	    /**
588	     * Look up the region whose inclusive postcode range contains this owner's
589	     * postcode, or {@code null} when the postcode is absent, malformed, or in no
590	     * known range.
591	     */
592	    private String regionForPostcode() {
593	        if (this.postcode == null || !this.postcode.matches("^[0-9]{4}$")) {
594	            return null;
595	        }
596	        int value = Integer.parseInt(this.postcode);
597	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
598	            int[] range = entry.getValue();
599	            if (value >= range[0] && value <= range[1]) {
600	                return entry.getKey();
601	            }
602	        }
603	        return null;
604	    }
605	
606	    /**
607	     * Return the owner's preferred contact channel, derived from the stored
608	     * contact details: {@code 'EMAIL'} when an email address is present,
609	     * otherwise {@code 'PHONE'}.
610	     */
611	    public String getContactPreference() {
612	        boolean hasEmail = this.email != null && !this.email.isBlank();
613	        return hasEmail ? "EMAIL" : "PHONE";
614	    }
615	
616	    /**
617	     * Return the owner's derived identity key, which consolidates all duplicate
618	     * detection into a single value formed as
619	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}.
620	     * The telephone and email are already stored in their normalized (E.164 /
621	     * lower-cased) forms; a missing email or household id contributes an empty
622	     * segment. A create is rejected only when a new owner's whole identity key
623	     * equals an existing owner's.
624	     */
625	    public String getIdentityKey() {
626	        String telephonePart = this.telephone == null ? "" : this.telephone;
627	        String emailPart = (this.email == null) ? "" : this.email;
628	        String householdPart = (this.householdId == null) ? "" : this.householdId;
629	        return telephonePart + "|" + emailPart + "|" + householdPart;
630	    }
631	
632	    protected Set<Pet> getPetsInternal() {
633	        if (this.pets == null) {
634	            this.pets = new HashSet<>();
635	        }
636	        return this.pets;
637	    }
638	
639	    protected void setPetsInternal(Set<Pet> pets) {
640	        this.pets = pets;
641	    }
642	
643	    public List<Pet> getPets() {
644	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
645	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
646	        return Collections.unmodifiableList(sortedPets);
647	    }
648	
649	    public void setPets(List<Pet> pets) {
650	        this.pets = new HashSet<>(pets);
651	    }
652	
653	    public void addPet(Pet pet) {
654	        getPetsInternal().add(pet);
655	        pet.setOwner(this);
656	    }
657	
658	    /**
659	     * Return the Pet with the given name, or null if none found for this Owner.
660	     *
661	     * @param name to test
662	     * @return true if pet name is already in use
663	     */
664	    public Pet getPet(String name) {
665	        return getPet(name, false);
666	    }
667	
668	    /**
669	     * Return the Pet with the given name, or null if none found for this Owner.
670	     *
671	     * @param name to test
672	     * @return true if pet name is already in use
673	     */
674	    public Pet getPet(String name, boolean ignoreNew) {
675	        name = name.toLowerCase();
676	        for (Pet pet : getPetsInternal()) {
677	            if (!ignoreNew || !pet.isNew()) {
678	                String compName = pet.getName();
679	                compName = compName.toLowerCase();
680	                if (compName.equals(name)) {
681	                    return pet;
682	                }
683	            }
684	        }
685	        return null;
686	    }
687	
688	    public Pet getPet(Integer petId) {
689	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
690	    }
691	
692	    @Override
693	    public String toString() {
694	        return new ToStringCreator(this)
695	
696	            .append("id", this.getId())
697	            .append("new", this.isNew())
698	            .append("lastName", this.getLastName())
699	            .append("firstName", this.getFirstName())
700	            .append("address", this.address)
701	            .append("city", this.city)
702	            .append("telephone", this.telephone)
703	            .append("email", this.email)
704	            .toString();
705	    }
706	}
